mapper.select:
SELECT t.replyId, t.questionId, t.userId, t.content, t.anonymity, t.likedTimes, t.replyTimes, t.createTime, t.hidden FROM ( SELECT r.id AS replyId, r.question_id AS questionId, r.user_id AS userId, r.content, r.anonymity, COALESCE(r.liked_times, 0) AS likedTimes, COALESCE(r.reply_times, 0) AS replyTimes, r.create_time AS createTime, r.hidden, ROW_NUMBER() OVER ( PARTITION BY r.question_id ORDER BY COALESCE(r.liked_times, 0) DESC, COALESCE(r.reply_times, 0) DESC, r.create_time DESC, r.id DESC ) AS rn FROM interaction_reply r WHERE r.question_id IN
#{questionId}
AND (r.answer_id = 0 OR r.answer_id IS NULL) AND (r.hidden = 0 OR r.hidden IS NULL) ) t WHERE t.rn <= #{limitPerQuestion} ORDER BY t.questionId, t.likedTimes DESC, t.replyTimes DESC, t.createTime DESC, t.replyId DESC
